INSERT INTO blog_edicao_posts (id, titulo, categoria, resumo, autor, tempo_leitura_min, data_publicacao, imagem_url, conteudo_md) VALUES
('art-atual-01', 'Inteligência Artificial e o Direito: Responsabilidade Civil dos Algoritmos', 'Atualidades Jurídicas', 'Quem responde por danos causados por sistemas autônomos e IAs generativas? O debate no Marco Legal da IA (PL 2338/2023).', 'Redação Estudos Jurídicos', 10, '2026-08-05', 'https://dnjrgpldcwcpoywamorr.supabase.co/storage/v1/object/public/blog-capas/atualidades.png', $md$O avanço da Inteligência Artificial Generativa e dos sistemas autônomos impõe desafios inéditos à teoria geral da **responsabilidade civil** no Direito brasileiro.$md$),
('art-atual-02', 'Direito dos Gamers e E-sports: Contratos, Direitos de Imagem e Propriedade Intelectual', 'Atualidades Jurídicas', 'Entenda como a Lei Geral do Esporte disciplina o mercado milionário de games, cyberatletas, contratos de trabalho e direitos de transmissão.', 'Redação Estudos Jurídicos', 9, '2026-08-04', 'https://dnjrgpldcwcpoywamorr.supabase.co/storage/v1/object/public/blog-capas/atualidades.png', $md$O mercado de e-sports movimenta bilhões de dólares e consolidou a profissão do pro-player, exigindo assessoria jurídica especializada.$md$),
('art-atual-03', 'Regulamentação das Apostas Esportivas (Bets) no Brasil: O Que Diz a Nova Lei', 'Atualidades Jurídicas', 'Analise a Lei nº 14.790/2023: tributação de operadoras e apostadores, regras de publicidade responsável e combate à manipulação de resultados.', 'Redação Estudos Jurídicos', 10, '2026-08-03', 'https://dnjrgpldcwcpoywamorr.supabase.co/storage/v1/object/public/blog-capas/atualidades.png', $md$A aprovação da **Lei nº 14.790/2023** regulamentou as apostas de quota fixa (bets) no Brasil, criando exigências de licença, tributação e integridade esportiva.$md$),
('art-atual-04', 'Trabalho em Plataformas Digitais (Uber/iFood): Vínculo Empregatício no TST', 'Atualidades Jurídicas', 'O debate constitucional e trabalhista sobre a subordinação algorítmica e a regulamentação dos motoristas e entregadores por aplicativo.', 'Redação Estudos Jurídicos', 10, '2026-08-02', 'https://dnjrgpldcwcpoywamorr.supabase.co/storage/v1/object/public/blog-capas/atualidades.png', $md$A relação de trabalho entre motoristas/entregadores e plataformas de tecnologia é um dos temas mais controversos do Direito do Trabalho atual.$md$),
('art-atual-05', 'Crimes Cibernéticos em 2026: Golpes do Pix, Engenharia Social e a Lei Carolina Dieckmann', 'Atualidades Jurídicas', 'Como o Direito Penal reprime a invasão de dispositivo (Art. 154-A do CP), fraudes eletrônicas e lavagem de dinheiro em ativos virtuais.', 'Redação Estudos Jurídicos', 9, '2026-08-01', 'https://dnjrgpldcwcpoywamorr.supabase.co/storage/v1/object/public/blog-capas/atualidades.png', $md$A criminalidade digital evoluiu rapidamente. O Código Penal foi atualizado com a Lei Carolina Dieckmann (Lei 12.737/12) e a Lei 14.155/21 para punir a fraude eletrônica com penas severas de 4 a 8 anos de reclusão.$md$);